Here is the commit message:
netrom: Fix a data-race around
 sysctl_netrom_transport_no_activity_timeout

We need to protect the reader reading the sysctl value because the
value can be changed concurrently.

Fixes: 1da177e4c3f4 ("Linux-2.6.12-rc2")
Signed-off-by: Jason Xing <kernelxing@tencent.com>
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The bug is caused by a data race condition where the value of `sysctl_netrom_transport_no_activity_timeout` can be modified concurrently while it is being read. This can lead to inconsistent or unexpected behavior in the application, as the reader may access a value that is in the process of being changed by another thread.

Here is the patch:

 static int nr_create(struct net *net, struct socket *sock, int protocol,
 		     int kern)
 {
 	struct sock *sk;
 	struct nr_sock *nr;

 	if (!net_eq(net, &init_net))
 		return -EAFNOSUPPORT;

 	if (sock->type != SOCK_SEQPACKET || protocol != 0)
 		return -ESOCKTNOSUPPORT;

 	sk = sk_alloc(net, PF_NETROM, GFP_ATOMIC, &nr_proto, kern);
 	if (sk  == NULL)
 		return -ENOMEM;

 	nr = nr_sk(sk);

 	sock_init_data(sock, sk);

 	sock->ops    = &nr_proto_ops;
 	sk->sk_protocol = protocol;

 	skb_queue_head_init(&nr->ack_queue);
 	skb_queue_head_init(&nr->reseq_queue);
 	skb_queue_head_init(&nr->frag_queue);

 	nr_init_timers(sk);

 	nr->t1     =
 		msecs_to_jiffies(READ_ONCE(sysctl_netrom_transport_timeout));
 	nr->t2     =
 		msecs_to_jiffies(READ_ONCE(sysctl_netrom_transport_acknowledge_delay));
 	nr->n2     =
 		msecs_to_jiffies(READ_ONCE(sysctl_netrom_transport_maximum_tries));
 	nr->t4     =
 		msecs_to_jiffies(READ_ONCE(sysctl_netrom_transport_busy_delay));
 	nr->idle   =
-		msecs_to_jiffies(sysctl_netrom_transport_no_activity_timeout);
+		msecs_to_jiffies(READ_ONCE(sysctl_netrom_transport_no_activity_timeout));
 	nr->window = READ_ONCE(sysctl_netrom_transport_requested_window_size);

 	nr->bpqext = 1;
 	nr->state  = NR_STATE_0;

 	return 0;
 }



